"use strict";(()=>{(async()=>{let c=await window.indexedDB.databases();if(c.length!==0){for(let t of c){let s=t.name;if(s)try{let n=await new Promise((o,r)=>{let e=window.indexedDB.open(s);e.onsuccess=()=>o(e.result),e.onerror=()=>r(e.error)}),i=Array.from(n.objectStoreNames),d={};for(let o of i)d[o]=await new Promise((r,e)=>{let a=n.transaction(o,"readonly").objectStore(o).getAll();a.onsuccess=()=>r(a.result),a.onerror=()=>e(a.error)});console.debug("IndexedDB:",s,d),n.close()}catch(n){console.debug("IndexedDB:",s,n)}}if(window.confirm("Clear IndexedDB?"))for(let t of await window.indexedDB.databases())t.name&&window.indexedDB.deleteDatabase(t.name)}})();})();
